@Service
public class OrderService {
    private final PaymentService paymentService;
    private final AuditService auditService;

    public OrderService(PaymentService paymentService, AuditService auditService) {
        this.paymentService = paymentService;
        this.auditService = auditService;
    }

    @Transactional(rollbackFor = Exception.class)
    public void createOrder(OrderCommand command) throws Exception {
        saveOrder(command);
        paymentService.pay(command);
        auditService.writeAudit(command); // REQUIRES_NEW 独立提交
    }
}

@Service
class AuditService {
    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public void writeAudit(OrderCommand command) {
        // 即使外层订单事务回滚，审计流水也可以独立提交
    }
}

// 典型失效：this 调用不会经过代理
@Transactional
public void outer() {
    this.inner(); // inner 的事务属性不会被代理拦截
}

@Transactional(propagation = Propagation.REQUIRES_NEW)
public void inner() { }
